  seed.heading,
  'published',
  target.base_order + seed.n,
  seed.content,
  jsonb_build_object(
    'seeded_by', '20261026120100_ielts_playbook_premium_advanced_labs',
    'pack', 'advanced_lab',
    'content_revision', 'premium-advanced-lab-2026-10',
    'source_file', 'content/ielts-playbook/premium-guides/guide-writing-task-2-premium.json'
  )
from target
cross join seed
on conflict (id) do nothing;

-- guide-speaking-band-7-premium: 24 sections, 5,391 words
with target as (
  select
    p.id as page_id,
    coalesce((
      select max(s.sort_order)
      from public.ielts_playbook_page_sections s
      where s.page_id = p.id
        and s.id <> all (array[md5('schood-ielts-pb-section:guide-speaking-band-7-premium:1')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:2')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:3')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:4')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:5')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:6')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:7')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:8')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:9')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:10')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:11')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:12')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:13')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:14')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:15')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:16')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:17')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:18')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:19')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:20')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:21')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:22')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:23')::uuid, md5('schood-ielts-pb-section:guide-speaking-band-7-premium:24')::uuid])
    ), 0) as base_order
  from public.ielts_playbook_pages p
  where p.locale_code = 'en'
    and p.slug = 'guide-speaking-band-7-premium'
),
seed(n, block_type, heading, content) as (
  values
    (1, 'rich_text', $ipb$Advanced Lab: How to Use This Section$ipb$, $ipb${"markdown":"The sections above explain what Band 7+ Speaking requires across fluency, vocabulary, grammar and pronunciation. This Advanced Lab turns that explanation into practice. It is designed for candidates who already speak at around Band 6 or 6.5 and want to understand, in concrete terms, what changes in a Band 7 or Band 8 performance.\n\nThe test itself lasts 11–14 minutes and has three parts: a short interview on familiar topics (Part 1), a long turn on a cue card with one minute of preparation and up to two minutes of speaking (Part 2), and a discussion of more abstract questions linked to the Part 2 topic (Part 3).\n\nIn this lab you will find:\n\n- **Decision rules** for how long to answer and how to extend an answer, part by part.\n- **Advanced techniques** for the planning minute, signposting, collocation, grammar and pronunciation.\n- **Side-by-side worked examples** of the same Part 2 and Part 3 answers at Band 6 and at Band 7–8 level, with criterion-by-criterion commentary.\n- **Timed drills** with model answers, an error-diagnosis table, a self-recording protocol and a 14-day schedule.\n\nRecord yourself for every drill. Speaking improves when you can hear the gap between what you meant to say and what you actually said. The band labels used in the examples describe typical features at those levels; they are teaching models, not official scores."}$ipb$::jsonb),
    (2, 'rich_text', $ipb$What Separates Band 7 from Band 8 in Speaking$ipb$, $ipb${"markdown":"Most candidates who reach Band 7 can already speak at length and use a range of vocabulary. The difference between 7 and 8 is mainly about *control*: how little effort the listener needs to follow you.\n\n### Fluency and Coherence\n\nAt 7, you speak at length without noticeable effort, though there may be occasional hesitation while you search for language, and some connectives may be repeated. At 8, hesitation is mostly about *content* (thinking what to say), not about *language* (searching for a word), and ideas are developed coherently and appropriately.\n\n### Lexical Resource\n\nAt 7, you use vocabulary flexibly, including some less common and idiomatic items, with awareness of style and collocation, though some choices are not quite right. At 8, you use a wide range readily and flexibly to convey precise meaning, and inaccuracies are only occasional.\n\n### Grammatical Range and Accuracy\n\nAt 7, you use a range of complex structures with some flexibility and frequently produce error-free sentences. At 8, most sentences are error-free and complex grammar appears naturally rather than deliberately.\n\n### Pronunciation\n\nAt 7, you are generally easy to understand and use a range of pronunciation features. At 8, you are easy to understand throughout, and features such as stress, rhythm and intonation are used to carry meaning; any accent has little effect on clarity.\n\n### The practical takeaway\n\nYou cannot jump to Band 8 by memorising impressive phrases. Examiners are trained to notice rehearsed language, and it usually sounds different in rhythm from spontaneous speech. The route to 8 is reducing language-search hesitation, increasing precision and making your voice support your meaning."}$ipb$::jsonb),
    (3, 'rich_text', $ipb$Decision Rules for Part 1 Answers$ipb$, $ipb${"markdown":"Part 1 lasts about four to five minutes. Its questions are simple, but many candidates either answer too briefly or turn every question into a speech. Use these rules.\n\n### Length rule\n\n- **If the question is factual** (*Do you work or study?*), then answer directly and add one or two sentences of relevant detail. About 15–25 seconds is enough.\n- **If the question asks for a preference or opinion** (*Do you prefer mornings or evenings?*), then answer, give a reason and add a brief example or contrast.\n- **If the examiner moves on before you finish**, then that is normal and not a penalty. The examiner has a time limit.\n\n### Extension rule: answer, reason, detail\n\n*Do you enjoy cooking?*\n*Answer:* Yes, more than I used to.\n*Reason:* It has become a way to switch off after work.\n*Detail:* I usually cook something simple on weekdays and try a new recipe at weekends.\n\n### Avoid these patterns\n\n- **The one-word answer.** *Yes. / Not really.* gives the examiner nothing to assess.\n- **The memorised opener.** *That's an interesting question* or *Well, to be honest with you* used every time quickly sounds rehearsed.\n- **The off-topic detour.** Long background stories reduce the time available for more questions, which means fewer chances to show range."}$ipb$::jsonb),
    (4, 'rich_text', $ipb$Decision Rules for Extending a Part 3 Answer$ipb$, $ipb${"markdown":"Part 3 is where Band 7 and 8 candidates separate themselves. The questions are abstract and often ask you to compare, evaluate, predict or explain. A strong answer usually runs to around 30–60 seconds and has a recognisable shape.\n\n### The extension menu\n\nAfter your direct answer, choose **two** of these moves:\n\n1. **Reason:** *The main reason is...*\n2. **Example:** *Take my own city, for instance...*\n3. **Contrast:** *That's different from how things worked a generation ago, when...*\n4. **Condition:** *It depends to some extent on whether...*\n5. **Consequence:** *What that means in practice is...*\n6. **Speculation:** *I suspect that in ten years...*\n\n### If/then decision rules\n\n- **If the question asks \"why\"**, then give a reason and a consequence.\n- **If the question asks you to compare** (past and present, young and old, cities and villages), then use contrast plus an example.\n- **If the question asks about the future**, then use speculation with appropriate hedging (*probably*, *I imagine*, *there's a good chance*) plus a condition.\n- **If the question asks whether something is good or bad**, then give a balanced view with a condition: *It's largely positive, provided that...*\n- **If you have no opinion on the topic**, then say so honestly and reason about it anyway: *I haven't thought much about it, but I'd guess that...* This is far better than silence.\n\n### Stop rule\n\nStop when your point is complete. Ending with a short summary sentence (*So on balance, I think it's a good thing*) signals that you have finished and keeps your answer coherent."}$ipb$::jsonb),
    (5, 'rich_text', $ipb$Advanced Technique: The Part 2 Planning Minute$ipb$, $ipb${"markdown":"You have exactly one minute to prepare and up to two minutes to speak. Many candidates waste the minute writing full sentences they then read aloud, which damages fluency. Use the minute to build a *route*, not a script.\n\n### The one-minute routine\n\n1. **Seconds 0–10: choose your story.** Pick the option you can talk about most concretely, even if it is not the most impressive. Specific memories produce natural detail.\n2. **Seconds 10–40: write four or five keywords**, one for each bullet point plus one extra for the *explain* part. Single words or short phrases only.\n3. **Seconds 40–55: note two precise words or collocations** you want to use, for example *patient*, *trial and error*, *second nature*.\n4. **Seconds 55–60: decide your first sentence.** Knowing how you will begin removes the most common moment of panic.\n\n### Speaking from the route\n\n- Spend most time on the *explain* bullet; it invites reflection, which shows higher-level language.\n- Move between points with natural signposts (*What I remember most clearly is...*, *The reason it stuck with me is...*).\n- If you finish early, add a reflection: how you feel about it now, what you would do differently, or how it compares with something else.\n\nThe examiner may stop you at two minutes. That is not a problem; it shows you could sustain the long turn."}$ipb$::jsonb),
    (6, 'rich_text', $ipb$Advanced Technique: Signposting Without Scripts$ipb$, $ipb${"markdown":"Signposting tells the listener where your answer is going. Used naturally, it improves Fluency and Coherence. Used mechanically, it makes you sound like a written essay read aloud.\n\n### Spoken versus written signposts\n\n| Written-style (avoid overusing) | Natural spoken alternatives |\n|---|---|\n| Firstly, secondly, finally | The first thing that comes to mind is... / On top of that... / And the last thing I'd say is... |\n| Moreover, furthermore | What's more... / And it's not just that... |\n| In conclusion | So overall... / So I suppose, on balance... |\n| However | Having said that... / Then again... / The flip side is... |\n| For example | Take... for instance / A good example would be... |\n\n### Method\n\n1. Learn three alternatives for each function: adding, contrasting, giving examples and concluding.\n2. In practice, deliberately use a *different* one each time for a week.\n3. After a week, stop thinking about them. They should now appear naturally when you need them.\n\n### Warning\n\nDo not stack signposts (*Well, actually, to be honest, I think that...*). One brief marker is enough before you get to the point."}$ipb$::jsonb),
    (7, 'rich_text', $ipb$Advanced Technique: Topic-Specific Collocation Banks$ipb$, $ipb${"markdown":"Lexical Resource at Band 7+ depends less on rare words and more on natural word partnerships. Examiners notice when a candidate says *do a mistake* instead of *make a mistake*, or *big rain* instead of *heavy rain*. Collocation banks help you build accurate, topic-ready phrases.\n\n### How to build a bank\n\n1. Choose one common IELTS topic: work, technology, the environment, family, education, health, travel, cities.\n2. Collect ten collocations for it from your own reading and listening: verb + noun, adjective + noun and adverb + adjective patterns.\n3. For each collocation, write one sentence about *your own life*.\n4. Use three of them in a recorded answer that day.\n\n### Example bank: work\n\n- *meet a deadline* / *miss a deadline*\n- *a heavy workload*\n- *strike a balance between work and family*\n- *take on responsibility*\n- *a steep learning curve*\n- *work remotely*\n- *climb the career ladder*\n- *job security*\n- *burn out*\n- *get on well with colleagues*\n\n### Personal sentence\n\n*When I started my current job there was a steep learning curve, and for the first few months I struggled to meet deadlines.*\n\nPersonal sentences matter: they make the language yours, so it appears naturally under pressure instead of sounding memorised."}$ipb$::jsonb),
    (8, 'rich_text', $ipb$Advanced Technique: Natural Grammar Range$ipb$, $ipb${"markdown":"In Speaking, grammar range should come from what you are trying to say. The trick is to choose question types that *invite* complex grammar and then let it appear.\n\n### Structures that arise naturally\n\n- **Past habits:** *I used to spend every summer at my grandmother's house.* / *She would always wake us up early.*\n- **Third conditional for reflection:** *If I hadn't taken that course, I probably wouldn't have changed careers.*\n- **Speculation about the future:** *I imagine more people will be working from home by then.* / *It's likely to get more expensive.*\n- **Relative clauses for precision:** *It's the kind of place where everyone knows each other.*\n- **Present perfect for experience and change:** *I've noticed that people have become much more careful about what they eat.*\n- **Comparatives with modifiers:** *It's considerably cheaper than it was* / *nowhere near as crowded as the city centre.*\n\n### Practice method: the tense map\n\nWhen you plan a Part 2 answer, note which time frames it touches: the past event, how you feel now, and what you might do in future. Covering all three time frames gives you natural opportunities for a range of tenses without forcing them.\n\n### Accuracy under pressure\n\nIf a complex sentence goes wrong, a quick natural self-correction (*...I've went, sorry, I've been there twice*) is fine. What lowers the score is a pattern of uncorrected errors in basic forms such as third-person *s*, past tense and articles."}$ipb$::jsonb),
    (9, 'rich_text', $ipb$Advanced Technique: Pronunciation Features That Carry Meaning$ipb$, $ipb${"markdown":"Pronunciation at Band 7+ is not about removing your accent. It is about using features that make your meaning clear: word stress, sentence stress, chunking and intonation.\n\n### Sentence stress: stressing the new or important word\n\nCompare:\n- *I didn't say she TOOK the book.* (She borrowed it, perhaps.)\n- *I didn't say SHE took the book.* (Someone else did.)\n\nIn your answers, stress the words that carry new information or contrast. This makes you easier to follow and signals control.\n\n### Chunking: pausing at natural boundaries\n\nListeners process speech in meaningful groups. Pausing *between* chunks sounds fluent; pausing *inside* them sounds hesitant.\n- Natural: *What I enjoyed most | was the fact that | nobody was in a hurry.*\n- Unnatural: *What I | enjoyed most was | the fact | that nobody.*\n\n### Intonation for lists and contrast\n\n- Rising tone on items in a list, falling on the last: *We had bread, cheese, fruit and some tea.*\n- A fall-rise on a point you will qualify: *It's convenient... but it's not cheap.*\n\n### Practice method\n\nChoose a 30-second section of a recording of yourself. Mark where you paused and which words you stressed. Then mark where you *should* have paused and what you *should* have stressed. Record it again. This targeted repetition is more useful than general \"speaking practice\"."}$ipb$::jsonb),
    (10, 'rich_text', $ipb$Worked Example: Part 2 Long Turn at Band 6$ipb$, $ipb${"markdown":"**Cue card (original):** *Describe a skill you learned from an older person. You should say: what the skill is, who taught it to you, how you learned it, and explain why it matters to you.*\n\n**Transcript (typical Band 6 features):**\n\n*OK, so I want to talk about, um, cooking. My grandmother teach me how to cook, er, plov, it is a traditional dish in my country. She is very good cook and she is cooking for many years. When I was child, maybe ten or eleven, I go to her house every weekend and she show me. First she cut the onion and the carrot, and then the meat, and, um, then she put the rice. It was very difficult for me because, um, the timing is very important. If you put the rice too early it is not good. So I was watching her many times and then I try myself. The first time it was, er, not so good, but my grandmother said it is OK. Um, why it is important for me... because it is, um, our tradition and also my grandmother is old now so I can cook for my family. I think it is very important skill. Also, um, cooking is useful for everybody. So that is why it is important for me.*"}$ipb$::jsonb),
    (11, 'rich_text', $ipb$The Same Long Turn at Band 7–8$ipb$, $ipb${"markdown":"**Transcript (typical Band 7–8 features):**\n\n*I'd like to talk about how my grandmother taught me to make plov, which is probably the most important dish in Uzbek family life, the kind of thing that turns up at every wedding and every big celebration.*\n\n*She learned it from her own mother, and she's been cooking it for well over fifty years, so by the time I was about ten she could practically do it with her eyes closed. Every Sunday I'd go round to her house, and at first she just let me watch. She'd fry the onions until they were deep golden, then add the meat and the carrots, which she always cut into long, thin strips. She never measured anything, which drove me mad at the time, because I wanted exact quantities.*\n\n*What I eventually realised was that the skill wasn't really about the recipe at all, it was about judgement: knowing by the sound of the oil when it's hot enough, or by the colour of the rice when it's ready to be covered. So it took a lot of trial and error. My first few attempts were frankly a disaster, but she was incredibly patient and just kept saying, \"Again, next week.\"*\n\n*As for why it matters, I suppose it's partly practical, since she can't stand at the stove for hours any more, so now I'm the one who cooks for family gatherings. But it's more than that. Every time I make it, I'm aware that I'm passing on something that's been handed down through several generations, and if I hadn't spent all those Sundays with her, that connection might simply have been lost.*"}$ipb$::jsonb),
    (12, 'rich_text', $ipb$Commentary: Part 2 Comparison$ipb$, $ipb${"markdown":"Both answers cover all four bullet points. The difference lies in how each criterion is met.\n\n### Fluency and Coherence\n\nThe Band 6 answer is willing to speak at length, but hesitation (*um*, *er*) comes mainly from searching for language, and the answer relies on simple connectors (*and then*, *so*, *also*). The ending repeats itself (*it is very important skill... that is why it is important for me*). The Band 7–8 answer moves smoothly between points with natural spoken signposts: *What I eventually realised was...*, *As for why it matters...*, *But it's more than that.* Ideas build towards a reflective conclusion rather than repeating.\n\n### Lexical Resource\n\nBand 6 vocabulary is adequate for the topic but general: *very good cook*, *very difficult*, *not so good*, *very important*. The Band 7–8 answer uses precise and idiomatic language naturally: *do it with her eyes closed*, *deep golden*, *drove me mad*, *trial and error*, *frankly a disaster*, *handed down through several generations*. None of it is forced; each phrase describes something specific.\n\n### Grammatical Range and Accuracy\n\nThe Band 6 answer has frequent errors in basic forms: *my grandmother teach me*, *she is cooking for many years* (present perfect needed), *I go to her house* for a past habit, *she show me*. The Band 7–8 answer uses a range of structures accurately: present perfect continuous (*she's been cooking it for well over fifty years*), past habit with *would* (*I'd go round*, *She'd fry*), relative clauses, a cleft sentence (*What I eventually realised was...*) and a third conditional (*if I hadn't spent all those Sundays...*).\n\n### Pronunciation\n\nOn paper we can only describe what a listener would notice. A Band 6 speaker may pause in the middle of phrases and give every word similar stress, so the listener must work harder. A Band 7–8 speaker chunks naturally (*every Sunday | I'd go round to her house*), stresses contrastive words (*it wasn't really about the RECIPE, it was about JUDGEMENT*), and uses falling intonation to close each point."}$ipb$::jsonb),
    (13, 'rich_text', $ipb$Worked Example: Part 3 at Band 6 and Band 8$ipb$, $ipb${"markdown":"**Examiner question (original):** *Do you think traditional skills like this will disappear in the future?*\n\n### Band 6-style answer\n\n*I think yes, maybe some skills will disappear, because young people now they use the internet for everything. For example, they can watch videos on YouTube and learn cooking. Also, many people are busy, they don't have time. But some skills will not disappear because they are important for the culture. So I think it is fifty-fifty.*\n\n### Band 8-style answer\n\n*I don't think they'll disappear altogether, but I do think the way they're passed on is changing quite dramatically. A generation ago, if you wanted to learn something like weaving or bread-making, you more or less had to learn it from a relative, standing next to them for years. Now a lot of that knowledge is being recorded online, which in one sense preserves it. The catch is that a video can show you the steps, but it can't really give you the judgement, the feel for when something's right, which only comes from practice and correction. So my guess is that the skills will survive, but in a slightly thinner form, unless families and schools make a deliberate effort to keep the hands-on side alive.*\n\n**Follow-up question:** *Should schools be responsible for teaching traditional skills?*\n\n### Band 8-style follow-up\n\n*To some extent, yes, though I'd be wary of making it just another exam subject, because that tends to drain the enjoyment out of it. I think schools are well placed to give children a first taste, a few workshops with local craftspeople, say, and then it's up to families and communities to take it further for those who are genuinely interested.*"}$ipb$::jsonb),
    (14, 'rich_text', $ipb$Commentary: Part 3 Comparison$ipb$, $ipb${"markdown":"### Fluency and Coherence\n\nThe Band 6 answer offers several reasons in a list (*because...*, *Also...*, *But...*) without developing any of them, then ends with a vague verdict (*fifty-fifty*). The Band 8 answer begins with a qualified position, develops one central idea (transmission is changing), introduces a contrast (videos versus judgement) and ends with a conditional prediction. It answers the question *and* explains the reasoning.\n\n### Lexical Resource\n\nBand 6 uses general words (*important*, *busy*, *use the internet for everything*). Band 8 uses precise and idiomatic choices: *disappear altogether*, *passed on*, *the catch is*, *a feel for when something's right*, *a slightly thinner form*, *drain the enjoyment out of it*, *give children a first taste*, *well placed to*.\n\n### Grammatical Range and Accuracy\n\nThe Band 6 answer contains a double subject (*young people now they use*) and run-on structures (*many people are busy, they don't have time*). The Band 8 answer uses a passive continuous (*is being recorded*), a conditional (*if you wanted to learn...*), a relative clause (*which only comes from practice*), *unless* to express a condition, and hedged speculation (*my guess is that...*, *I'd be wary of...*). Errors are absent.\n\n### Pronunciation\n\nThe Band 8 answer relies on stress to signal contrast (*a video can show you the STEPS, but it can't give you the JUDGEMENT*) and on a fall-rise for its qualified opening (*I don't think they'll disappear altogether... but*). These features help the listener follow an abstract argument without effort.\n\n### The extension menu in action\n\nMap the Band 8 answer onto the extension menu: direct answer (not altogether), contrast (a generation ago versus now), consequence (knowledge recorded online), condition (*unless* families and schools act) and speculation (*my guess is*). Two or three of these moves, used naturally, are what make a Part 3 answer feel complete."}$ipb$::jsonb),
    (15, 'rich_text', $ipb$Error-Diagnosis Table$ipb$, $ipb${"markdown":"Listen to a recording of yourself, find the symptom, check the likely cause and apply the fix in your next practice session.\n\n| Symptom | Likely cause | Fix |\n|---|---|---|\n| Long pauses mid-sentence | Searching for vocabulary in real time | Build collocation banks for common topics; practise paraphrasing around missing words |\n| Answers stop after one sentence | No extension routine | Use answer-reason-detail in Part 1 and the extension menu in Part 3 |\n| Part 2 ends well before two minutes | Planning minute spent writing sentences | Use the one-minute route; spend most time on the *explain* bullet |\n| Repeating *very important*, *very good* | Limited evaluative vocabulary | Learn precise alternatives: *essential*, *invaluable*, *rewarding*, *worthwhile* |\n| Same connectors in every answer | Written-style signposts | Learn natural spoken alternatives and rotate them |\n| Basic errors in past tense or third person | Accuracy drops under pressure | Slow down slightly; record and correct one tense per week |\n| Flat, monotone delivery | Every word stressed equally | Mark stress on contrast and new information in a transcript; re-record |\n| Answers sound memorised | Rehearsed openers or full scripted answers | Prepare ideas and collocations, never full sentences |\n| Going silent on abstract questions | No strategy for unfamiliar topics | Use the honest-reasoning rule: admit it, then speculate with hedging |\n| Over-long answers in Part 1 | Treating Part 1 like Part 3 | Keep Part 1 answers to about 15–25 seconds |"}$ipb$::jsonb),
    (16, 'rich_text', $ipb$Timed Drill 1: Two-Minute Long Turn With One-Minute Plan$ipb$, $ipb${"markdown":"**Time limit: 1 minute preparation, then up to 2 minutes speaking. Record yourself.**\n\n*Describe a time when you had to change your plans at the last minute. You should say: what the original plan was, why it changed, what you did instead, and explain how you felt about the change.*\n\nRequirements:\n\n1. Use the one-minute routine: no full sentences in your notes.\n2. Include at least one past habit or past continuous form, and one reflection using a conditional.\n3. Spend at least 30 seconds on the *explain* bullet.\n\nAfter recording, count your language-search pauses (pauses where you were looking for a word rather than an idea). Write the number down. Repeat the same card the next day and try to reduce it.\n\nA model route and a sample opening are in **Drill Answers**."}$ipb$::jsonb),
    (17, 'rich_text', $ipb$Timed Drill 2: Ninety-Second Part 3 Extension$ipb$, $ipb${"markdown":"**Time limit: 90 seconds per question. Record yourself.**\n\nAnswer each question using a direct answer plus at least two moves from the extension menu (reason, example, contrast, condition, consequence, speculation). Name the moves you used after each answer.\n\n1. *Why do some people prefer to shop in small local shops rather than large supermarkets?*\n2. *How has the way people communicate with their families changed in recent years?*\n3. *Will cities become more or less crowded in the future?*\n\nThen listen back and check: Did you begin with a direct answer? Did you end with a clear closing sentence?\n\nModel answers are in **Drill Answers**."}$ipb$::jsonb),
    (18, 'rich_text', $ipb$Timed Drill 3: Paraphrase Sprint$ipb$, $ipb${"markdown":"**Time limit: 20 seconds per item.**\n\nImagine you cannot remember the word in bold. Say a full sentence that communicates the same meaning *without* using it. This builds the skill of talking around missing vocabulary, which protects fluency.\n\n1. I felt **nostalgic** when I visited my old school.\n2. The new policy was very **controversial**.\n3. My brother is extremely **punctual**.\n4. The town has become very **gentrified**.\n5. She is a very **resilient** person.\n6. The film was **overrated**.\n\nRecord all six in one take, then compare with the answer key."}$ipb$::jsonb),
    (19, 'rich_text', $ipb$Drill Answers$ipb$, $ipb${"markdown":"### Drill 1: model route\n\nNotes: *concert tickets / storm, cancelled / cousin's house, board games / disappointed then grateful*. Collocations: *last-minute change*, *make the best of it*.\n\nSample opening: *I'd like to talk about a weekend last spring when a storm completely ruined the plans I'd been looking forward to for months. My friends and I had bought tickets for an open-air concert...*\n\nReflection for the *explain* bullet: *At the time I was really frustrated, but looking back, if the concert had gone ahead, I wouldn't have spent that evening with my cousins, and it turned out to be one of the best nights of the year.*\n\n### Drill 2: model answers\n\n**1.** *Mainly because of the personal touch, I think. In a small shop the owner often knows you by name and can recommend things, which you'd never get in a huge supermarket* (reason, contrast). *There's also a sense of supporting the neighbourhood: if everyone shopped at the big chains, a lot of those local businesses would simply close* (condition, consequence).\n\n**2.** *It's become far more constant but perhaps less deep. When my parents were young, they might phone home once a week, whereas now families have group chats running all day* (contrast, example). *The downside is that quick messages can replace proper conversations, so people feel connected without really talking* (consequence).\n\n**3.** *Probably more crowded, at least in the short term, because that's where the jobs are concentrated* (speculation, reason). *That said, if remote work keeps spreading, some people may move to smaller towns, so I'd expect growth to slow rather than stop* (condition, speculation).\n\n### Drill 3: answer key (one possible version each)\n\n1. I remembered the good times I used to have there and felt a little sad that they were over.\n2. Some people strongly supported it, while others were completely against it.\n3. He is never late; he always arrives exactly on time.\n4. Richer people have moved in, prices have gone up and many of the original residents have left.\n5. Whenever something goes wrong, she recovers quickly and keeps going.\n6. Everyone said it was brilliant, but I thought it was much less impressive than people claimed."}$ipb$::jsonb),
    (20, 'callout', $ipb$When Your Mind Goes Blank$ipb$, $ipb${"label":"Recovery rule","body":"If you cannot think of anything to say, do not stay silent. Buy two or three seconds with a natural phrase (*That's not something I've thought about much, but...*), then answer the simplest version of the question honestly and add one reason. If you lose a word, describe it instead of stopping. Calm, natural recovery shows the fluency and flexibility examiners are listening for; a long silence gives them nothing to assess."}$ipb$::jsonb),
    (21, 'rich_text', $ipb$Self-Recording Review Protocol$ipb$, $ipb${"markdown":"Recording is only useful if you review it systematically. Use this 15-minute protocol after each practice session.\n\n### Step 1: listen once without stopping (3 minutes)\n\nNote your overall impression: did you sound comfortable, rushed or hesitant? Would a stranger understand you without effort?\n\n### Step 2: transcribe 30 seconds (5 minutes)\n\nWrite down exactly what you said, including *um*, repetitions and errors. Transcription reveals problems that you do not notice while listening.\n\n### Step 3: mark the transcript (4 minutes)\n\n- Circle every grammar error.\n- Underline every general word (*good*, *nice*, *thing*, *very*) that could be more precise.\n- Mark pauses with a slash and check whether they fall between or inside phrases.\n- Count the connectors and note any repeated ones.\n\n### Step 4: re-record the same answer (3 minutes)\n\nDo not read your corrected transcript aloud. Speak again from memory, applying the corrections. Compare the two recordings.\n\n### Track over time\n\nKeep a simple log with three columns: date, language-search pauses in 30 seconds, and grammar errors in 30 seconds. Over two weeks, these two numbers are a more honest measure of progress than how confident you feel."}$ipb$::jsonb),
    (22, 'rich_text', $ipb$14-Day Advanced Repair Schedule$ipb$, $ipb${"markdown":"Plan for about 40–60 minutes a day. Record every session.\n\n| Day | Focus | Task |\n|---|---|---|\n| 1 | Baseline | Record a full mock: five Part 1 questions, one Part 2 card, four Part 3 questions. Run the review protocol. |\n| 2 | Part 1 rules | Answer 15 Part 1 questions using answer-reason-detail. Keep each to 15–25 seconds. |\n| 3 | Collocations | Build banks for work and technology; record a 1-minute answer on each using five collocations. |\n| 4 | Planning minute | Practise four Part 2 cards with the one-minute route. |\n| 5 | Part 3 extension | Answer eight Part 3 questions, naming the extension moves after each. |\n| 6 | Signposting | Re-record Day 4 cards using a different spoken signpost each time. |\n| 7 | Review | Repeat the Day 1 mock with new questions. Compare pause and error counts. |\n| 8 | Grammar range | Plan two Part 2 cards with a tense map; include a past habit and a conditional reflection. |\n| 9 | Pronunciation | Mark stress and chunks in a 30-second transcript; re-record three times. |\n| 10 | Paraphrase | Two rounds of the paraphrase sprint with new words; then a Part 3 set. |\n| 11 | Collocations | Build banks for environment and education; use them in Part 3 answers. |\n| 12 | Abstract questions | Answer six unfamiliar Part 3 questions using the honest-reasoning rule. |\n| 13 | Full mock | Full timed mock, ideally with a partner acting as examiner. |\n| 14 | Consolidation | Compare Day 1, 7 and 13 recordings. Write down the one habit that still needs work. |\n\nIf possible, have a qualified teacher listen to your Day 7 and Day 13 recordings. An experienced listener can identify pronunciation patterns that are hard to hear in your own voice."}$ipb$::jsonb),
    (23, 'faq', $ipb$Advanced Lab FAQ$ipb$, $ipb${"items":[{"question":"Should I try to change my accent to reach Band 8?","answer":"No. Accent itself is not the problem. What matters is how easily you are understood and how well you use stress, chunking and intonation to support meaning."},{"question":"Is it acceptable to ask the examiner to repeat a question?","answer":"Yes. Asking for a repetition occasionally is natural and does not lower your score. In Part 1 the examiner will normally just repeat the question, while in Part 3 they can usually rephrase it if you are unsure what it means."},{"question":"How long should my Part 3 answers be?","answer":"Long enough to develop the point, usually around 30 to 60 seconds. A direct answer plus two extension moves is a good target. Very long answers can lose coherence."},{"question":"Do I have to tell the truth in Part 2?","answer":"You are assessed on your language, not on whether the story is true. However, real memories usually produce more natural, specific detail, so choose a true story when you can."},{"question":"Will idioms raise my score?","answer":"Only when they are accurate and natural in context. A forced or slightly wrong idiom can sound rehearsed. Natural collocations are a safer route to a higher Lexical Resource score."},{"question":"What if I make a mistake and notice it?","answer":"Correct it briefly and continue. Natural self-correction is part of fluent speech. Do not stop to apologise at length or restart the whole answer."}]}$ipb$::jsonb),
    (24, 'checklist', $ipb$Advanced Lab Final Checklist$ipb$, $ipb${"items":["My Part 1 answers follow answer, reason, detail and last about 15–25 seconds.","In the Part 2 planning minute I write a route of keywords, not sentences.","I spend real time on the explain bullet and add a reflection if I finish early.","My Part 3 answers start directly and use at least two extension moves.","I close each Part 3 answer with a clear summary sentence.","I use natural spoken signposts and rotate them rather than repeating one.","I have collocation banks for at least six common topics, each with personal sentences.","My grammar range comes from time frames and reflection, not from forced structures.","I stress contrast and new information and pause between meaningful chunks.","When I lose a word, I describe it rather than stopping.","I review every recording with the protocol and track pauses and errors over time."]}$ipb$::jsonb)
)
insert into public.ielts_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select
  md5('schood-ielts-pb-section:' || 'guide-speaking-band-7-premium' || ':' || seed.n)::uuid,
  target.page_id,
  seed.block_type,
  seed.heading,
  'published',
  target.base_order + seed.n,
  seed.content,
  jsonb_build_object(
    'seeded_by', '20261026120100_ielts_playbook_premium_advanced_labs',
    'pack', 'advanced_lab',
    'content_revision', 'premium-advanced-lab-2026-10',
    'source_file', 'content/ielts-playbook/premium-guides/guide-speaking-band-7-premium.json'
  )
from target
cross join seed
on conflict (id) do nothing;

-- guide-band-6-to-7-roadmap: 24 sections, 5,189 words
with target as (
  select
    p.id as page_id,
    coalesce((
      select max(s.sort_order)
      from public.ielts_playbook_page_sections s
      where s.page_id = p.id
        and s.id <> all (array[md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:1')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:2')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:3')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:4')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:5')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:6')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:7')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:8')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:9')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:10')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:11')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:12')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:13')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:14')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:15')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:16')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:17')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:18')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:19')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:20')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:21')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:22')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:23')::uuid, md5('schood-ielts-pb-section:guide-band-6-to-7-roadmap:24')::uuid])
    ), 0) as base_order
  from public.ielts_playbook_pages p
  where p.locale_code = 'en'
    and p.slug = 'guide-band-6-to-7-roadmap'
),
seed(n, block_type, heading, content) as (
  values
    (1, 'rich_text', $ipb$Advanced Lab: How to Use This Section$ipb$, $ipb${"markdown":"Everything above this point explains the road from Band 6 to Band 7. This Advanced Lab is the workshop. It assumes you already know the four skills, the band descriptors in broad terms and the eight-week outline earlier in this guide. Here you will do the arithmetic, run the diagnostics and make the decisions that most candidates leave to luck.\n\nWork through the Lab in three passes:\n\n1. **Measure.** Read the arithmetic and minimum-score sections, then work out exactly which combination of section bands gets you to your target. Do this before you study anything else this week.\n2. **Diagnose.** Use the before-and-after examples, the error-diagnosis table and the decision rules to find the one or two behaviours that are actually holding your score down.\n3. **Train.** Complete the three timed drills, check the answer key honestly, then run the 14-day breakthrough block.\n\nKeep a single notebook or document for this Lab. Every number you write in it should come from real evidence: a marked practice test, a timed section in the simulator, a teacher's assessment against the criteria, or an official result. Feelings and guesses go in a separate column labelled \"impression\" so they never contaminate your tracker."}$ipb$::jsonb),
    (2, 'rich_text', $ipb$The Overall Band Arithmetic, Done Properly$ipb$, $ipb${"markdown":"Your overall band is the mean of your four section bands, rounded to the nearest whole or half band. The rounding rule has two details that matter for planning:\n\n- If the mean ends in **.25**, it is rounded **up** to the next half band (6.25 becomes 6.5).\n- If the mean ends in **.75**, it is rounded **up** to the next whole band (6.75 becomes 7.0).\n- Means ending in .125 or .625 round **down** to the nearest half or whole band; means ending in .375 or .875 round **up**.\n\nBecause every section band is a whole or half number, the sum of your four bands always moves in steps of 0.5, and the mean moves in steps of 0.125. That gives you a simple shortcut: **add the four bands and look at the total.**\n\n| Section bands (L / R / W / S) | Total | Mean | Overall |\n|---|---|---|---|\n| 7.0 / 6.5 / 6.0 / 6.5 | 26.0 | 6.5 | 6.5 |\n| 7.0 / 6.5 / 6.5 / 6.5 | 26.5 | 6.625 | 6.5 |\n| 7.0 / 7.0 / 6.5 / 6.5 | 27.0 | 6.75 | 7.0 |\n| 7.5 / 7.0 / 6.5 / 6.5 | 27.5 | 6.875 | 7.0 |\n| 6.5 / 6.5 / 6.0 / 6.0 | 25.0 | 6.25 | 6.5 |\n| 6.0 / 6.0 / 6.0 / 6.5 | 24.5 | 6.125 | 6.0 |\n\nThe practical rule that falls out of this table: **an overall 7.0 needs a total of at least 27.0.** An overall 6.5 needs at least 25.0. If your current total is 26.0, you are exactly two half-band steps away from 7.0 overall. It does not matter, for the overall, which two skills provide those steps. It matters enormously for the section minimums, which is the next section."}$ipb$::jsonb),
    (3, 'rich_text', $ipb$Why Section Minimums Beat the Overall$ipb$, $ipb${"markdown":"Many universities, employers and visa schemes publish a requirement in two parts: an overall band and a minimum for every section, or for specific sections. A typical shape is \"7.0 overall with no band below 6.5\", or \"7.0 overall with at least 7.0 in Writing\". The second number is the one that decides whether your result is accepted.\n\nConsider two fictional candidates aiming for \"7.0 overall, no band below 6.5\":\n\n- **Candidate P:** L 8.0, R 7.5, W 6.0, S 6.5. Total 28.0, mean 7.0, overall 7.0. **Rejected**, because Writing is 6.0.\n- **Candidate Q:** L 7.0, R 7.0, W 6.5, S 6.5. Total 27.0, mean 6.75, overall 7.0. **Accepted**, despite a lower total than Candidate P.\n\nCandidate P studied harder in the skills that were already strong, because progress there felt quicker. Candidate Q studied where the requirement bit. The lesson is that the overall band is a consequence; the minimums are the constraint. Plan around the constraint first.\n\nAlways copy the exact requirement wording from the receiving organisation's official page into your Lab notebook, including which test type it accepts and how recent the result must be. Requirements change, and departments within the same university can differ. If the wording is ambiguous, ask the organisation in writing before you book."}$ipb$::jsonb),
    (4, 'rich_text', $ipb$Reverse-Engineering Your Cheapest Path to 7.0$ipb$, $ipb${"markdown":"The \"cheapest path\" is the combination of half-band gains that satisfies every requirement with the least total effort. Find it in four steps.\n\n**Step 1: List the hard floors.** Write each section's minimum next to your current evidence. Any section below its floor must rise, whatever else happens. These are your compulsory gains.\n\n**Step 2: Count the remaining total gap.** Add your current bands, add the compulsory gains, and compare the new total with 27.0 (for 7.0 overall). The difference is your optional gap, measured in half-band steps.\n\n**Step 3: Price each optional step.** For each skill, estimate how hard the next half band is, using your error logs rather than your mood. A skill where your errors are mostly careless (transfer mistakes, spelling, running out of time on the last passage) is cheap. A skill where errors come from range or accuracy you do not yet have is expensive.\n\n**Step 4: Buy the cheapest steps first, with a safety margin.** Plan for one half-band step more than the arithmetic requires. Test-day variation is real, and a plan that only works if everything goes perfectly is not a plan.\n\nMost Band 6.5 candidates discover that one receptive skill (Listening or Reading) offers a cheap step through error discipline, while Writing or Speaking contains the compulsory step. That combination, one cheap step plus one compulsory step, is the most common shape of a realistic route to 7.0."}$ipb$::jsonb),
    (5, 'rich_text', $ipb$Worked Profile A: The Writing Bottleneck$ipb$, $ipb${"markdown":"**Candidate A** (fictional): L 7.0, R 6.5, W 6.0, S 6.5. Needs 7.0 overall with no band below 6.5. Ten weeks available. Evidence: two full simulator tests and four marked essays.\n\n**Arithmetic.** Current total 26.0, overall 6.5. Writing 6.0 is below the 6.5 floor, so one Writing step is compulsory. After that step the total is 26.5, still overall 6.5. One more step is needed to reach 27.0.\n\n**Pricing the optional step.** Candidate A's Reading log shows that most lost marks come from True/False/Not Given questions answered from memory rather than from the text, and from leaving the last six questions of passage three rushed. Both are discipline problems: cheap. Listening is already 7.0 and the remaining errors are spread thinly, so the next step there is expensive. Speaking errors are grammatical range in Part 3: medium cost.\n\n**Decision.** Compulsory step: Writing 6.0 to 6.5 (task response and paragraph development in Task 2, overview in Task 1). Optional step: Reading 6.5 to 7.0 through an evidence-first TFNG routine and a fixed passage-time budget. Safety step: Speaking 6.5 to 7.0 is the stretch goal, trained lightly through Part 3 extension practice.\n\n**What Candidate A stops doing:** extra Listening practice tests, which were comfortable but no longer moved the plan."}$ipb$::jsonb),
    (6, 'rich_text', $ipb$Worked Profile B: The Uneven High Scorer$ipb$, $ipb${"markdown":"**Candidate B** (fictional): L 8.0, R 8.0, W 6.0, S 6.0. Needs 7.0 overall with at least 6.5 in each section. Six weeks available.\n\n**Arithmetic.** Total 28.0, mean 7.0, overall 7.0 already. The overall target is met; the result is still unusable because two sections are below the floor. The only work that matters is Writing 6.0 to 6.5 and Speaking 6.0 to 6.5.\n\n**The trap.** Candidate B's receptive scores suggest strong English, so the instinct is to \"polish\" with advanced vocabulary. Their marked essays, however, show a different problem: positions that drift between paragraphs and examples that are asserted rather than explained. Their Speaking recordings show short Part 1 answers and Part 2 talks that end after about a minute. Neither problem is fixed by rarer words.\n\n**Decision.** Zero new Reading or Listening practice beyond one maintenance test every two weeks. Writing: a clear position stated in the introduction and restated consistently, two body paragraphs each built as claim, explanation, example, link. Speaking: Part 2 talks timed to the full two minutes, Part 1 answers extended with a reason and a detail, Part 3 answers that compare and qualify.\n\n**Booking decision.** Book only after three consecutive marked essays and two recorded mock interviews reach the floor on the criteria, not after one good day."}$ipb$::jsonb),
    (7, 'rich_text', $ipb$Worked Profile C: The Flat 6.5$ipb$, $ipb${"markdown":"**Candidate C** (fictional): L 6.5, R 6.5, W 6.5, S 6.5. Needs 7.0 overall, no individual minimum. Twelve weeks available.\n\n**Arithmetic.** Total 26.0. Needs 27.0, which means two half-band steps anywhere. No compulsory steps exist, which sounds like freedom but often produces drift: candidates spread effort evenly and nothing crosses a boundary.\n\n**Pricing.** Candidate C's logs show Listening errors clustered in Part 4 note completion (spelling and word limits), and Reading errors clustered in matching headings. Writing and Speaking errors are broad: range, accuracy and development all slightly short.\n\n**Decision.** Buy the two cheapest steps: Listening through a spelling and word-limit discipline routine plus Part 4 prediction practice, and Reading through a headings method that summarises each paragraph's main idea before looking at the options. Keep Writing and Speaking on maintenance so they do not slip; a fall from 6.5 to 6.0 in either would cancel one of the gains.\n\n**Key insight.** With no minimums, a flat profile can reach 7.0 without touching its hardest skill at all. That is legitimate, and often the fastest route, provided the plan protects the other two skills from slipping."}$ipb$::jsonb),
    (8, 'rich_text', $ipb$Writing at Band 7: Before and After$ipb$, $ipb${"markdown":"The difference between a Band 6 and a Band 7 Writing response is usually not vocabulary level. It is control: a clear position, ideas that are explained, and language that is precise rather than decorative.\n\n### Development\n\n**Band 6 shape:** \"Public transport is important for cities. It reduces pollution and traffic. Therefore governments should invest more money in it.\"\n\n**Band 7 shape:** \"Investing in public transport cuts congestion more effectively than building roads, because each new bus lane moves far more people per hour than the car lane it replaces. In cities where commuting by car is the default, this shift also lowers emissions without asking residents to change where they live.\"\n\nThe second version makes one claim, explains why it is true, and adds a consequence. It answers \"why?\" before the examiner has to ask.\n\n### Position\n\n**Band 6 shape:** an introduction that says \"this essay will discuss both views\" and a conclusion that suddenly agrees with one of them.\n\n**Band 7 shape:** \"While remote work suits some roles, I believe most organisations benefit from requiring staff in the office for part of the week.\" The same position then appears in every body paragraph and the conclusion.\n\n### Task 1 overview\n\n**Band 6 shape:** a list of every number in the chart, with no summary.\n\n**Band 7 shape:** \"Overall, spending on housing rose steadily throughout the period, while spending on entertainment remained the smallest category in every year shown.\" Two sentences that tell the reader what matters before any detail.\n\nRewrite one of your own old paragraphs in each of these three ways this week. The rewrite teaches more than a new essay."}$ipb$::jsonb),
    (9, 'rich_text', $ipb$Speaking at Band 7: Before and After$ipb$, $ipb${"markdown":"Band 7 Speaking sounds like someone thinking aloud in English with some flexibility, not someone reciting.\n\n### Part 1\n\n**Question:** \"Do you enjoy cooking?\"\n\n**Band 6 shape:** \"Yes, I enjoy cooking. I cook every day. It is my hobby.\"\n\n**Band 7 shape:** \"I do, though mostly at weekends. During the week I just make something quick, but on Saturdays I like trying a recipe I haven't attempted before, which is usually a bit chaotic but fun.\"\n\nThe upgrade adds a contrast (though, but), a time frame and a small personal detail. Nothing in it is memorised.\n\n### Part 3\n\n**Question:** \"Why do some people prefer to live in small towns?\"\n\n**Band 6 shape:** \"Because small towns are quiet and cheap. Big cities are noisy and expensive.\"\n\n**Band 7 shape:** \"Partly it's about cost, since housing tends to be cheaper, but I think the bigger reason is a sense of belonging. In a small town you see the same faces every day, and for some people that matters more than having endless choice. Having said that, younger people often feel the opposite way, because the opportunities they want are concentrated in cities.\"\n\nThe upgrade gives a reason, ranks reasons, and qualifies the answer by considering a different group. Comparing, ranking and qualifying are the three Part 3 moves that most reliably signal Band 7 range.\n\n### Recovery\n\nWhen you lose a word, paraphrase instead of stopping: \"it's a sort of... the tool you use to open tins\". Smooth recovery protects fluency, which a long silence damages."}$ipb$::jsonb),
    (10, 'rich_text', $ipb$Reading at Band 7: The Error Log Upgrade$ipb$, $ipb${"markdown":"A Band 6 error log records what went wrong. A Band 7 error log records why, and what you will do differently on the next passage.\n\n**Band 6 entry:**\n\"Q23 wrong. Answered True, answer was Not Given.\"\n\n**Band 7 entry:**\n\"Q23 (TFNG). I chose True. The statement said the scheme was *successful*; the text said it was *popular with residents*. I treated popular as successful. Rule: a statement needs evidence for every key claim, including evaluation words. Next time I will underline the evaluation word in the statement and look for evidence of that exact judgement.\"\n\nThe upgraded entry has four parts: question type, what you chose, the precise gap between statement and text, and a reusable rule. After twenty entries like this, patterns appear: perhaps most of your errors are evaluation words, quantity words (some, most, all), or time words (now, previously, will). Each pattern becomes one targeted rule.\n\n### Timing evidence\n\nRecord the time you finish each passage in every timed test. If passage three regularly starts with less than twenty minutes left, your issue is partly allocation rather than understanding. A fixed budget (for example, leaving passage one at a set clock time no matter what) is a cheap half-band for many candidates."}$ipb$::jsonb),
    (11, 'rich_text', $ipb$Listening at Band 7: The Error Log Upgrade$ipb$, $ipb${"markdown":"Listening errors feel random, which is why candidates rarely log them properly. They are not random.\n\n**Band 6 entry:**\n\"Part 2 Q14 wrong. Didn't hear.\"\n\n**Band 7 entry:**\n\"Part 2 Q14 (map labelling). I wrote the café, answer was the gift shop. The speaker first said 'the café used to be next to the entrance', then corrected it: 'it's now moved to the back'. I wrote the first location I heard. Rule: in map and plan questions, wait for the end of the sentence before writing, because past locations are a common distractor.\"\n\n### Four error families to tag\n\n- **Correction errors:** you wrote the first answer and missed the change.\n- **Form errors:** spelling, plurals, word limits, number formats.\n- **Location errors:** you lost your place and missed two or three answers in a row.\n- **Meaning errors:** you heard the words but did not recognise the paraphrase.\n\nTag every wrong answer with one family. If form errors make up a large share of your list, you have the cheapest half-band in the whole test available: a careful transfer and spelling routine. If location errors dominate, practise following the question order with your eyes slightly ahead of the audio."}$ipb$::jsonb),
    (12, 'rich_text', $ipb$Error Diagnosis Table$ipb$, $ipb${"markdown":"Use this table after every marked test. Find the symptom you see, check whether the likely cause matches your evidence, and apply the fix for two weeks before judging it.\n\n| Symptom | Likely cause | Fix |\n|---|---|---|\n| Writing stuck at 6.0 despite strong vocabulary | Ideas listed, not explained | Each body paragraph: claim, why, example, so what |\n| Task 1 marked down despite accurate numbers | No overview, or overview hidden at the end | Write a two-sentence overview before any detail |\n| Speaking Part 2 ends early | No structure for the long turn | Plan four prompts: what, when, why, how you felt |\n| Speaking marked as limited range | Safe short answers in Part 3 | Compare, rank and qualify in every Part 3 answer |\n| Reading TFNG errors in clusters | Answering from knowledge, not text | Underline key claim words; demand evidence for each |\n| Last Reading passage always rushed | No time budget | Fixed exit time for passages one and two |\n| Listening errors in two or three consecutive answers | Lost place | Read one question ahead; mark a skip and move on |\n| Listening answers correct but marked wrong | Spelling, plurals, word limit | Slow transfer check against the instruction |\n| Scores swing by a band between tests | Practice conditions not consistent | Same timing, same order, no pauses, every test |"}$ipb$::jsonb),
    (13, 'rich_text', $ipb$Decision Rules for Where the Next Hour Goes$ipb$, $ipb${"markdown":"When you sit down to study, use these rules in order. Stop at the first one that applies.\n\n1. **If** any section is below its required minimum, **then** the hour goes to that section. If two are below, alternate days, starting with the larger gap.\n2. **If** a section has an error family that makes up most of its recent mistakes, **then** spend the hour on that family only (one drill type, one rule, repeated).\n3. **If** you have not done a full timed test in the past fourteen days, **then** the hour (or the next three hours) goes to a full timed test under real conditions.\n4. **If** your last two Writing tasks were not marked against the criteria, **then** get one marked or self-assess carefully with the public band descriptors before writing more.\n5. **If** none of the above apply, **then** spend the hour on the cheapest optional half-band from your cheapest-path calculation.\n\nTwo anti-rules:\n\n- **If** a task feels comfortable and enjoyable, **then** check whether it still moves your plan. Comfort is often a sign of maintenance, not progress.\n- **If** you are tempted to start a new resource, **then** first finish reviewing the mistakes from the last one."}$ipb$::jsonb),
    (14, 'rich_text', $ipb$Decision Tree: Ready to Book or Not Yet$ipb$, $ipb${"markdown":"Answer each question with evidence from the last three weeks only.\n\n**Q1. Have you completed at least two full timed tests under real conditions in the last three weeks?**\n- No: not ready. Schedule them first.\n- Yes: go to Q2.\n\n**Q2. In both tests, did every section meet its required minimum?**\n- No: not ready. Return to the decision rules; the failing section gets priority.\n- Yes: go to Q3.\n\n**Q3. Did the total of your four section bands reach the target total (27.0 for 7.0 overall) in both tests?**\n- No, but within one half-band step: borderline. Go to Q4.\n- No, by two or more steps: not ready. Rebuild the cheapest path.\n- Yes: go to Q5.\n\n**Q4. Is the missing step in a skill whose errors are mostly discipline (form, timing, place)?**\n- Yes: book with a two-to-three week runway and train that discipline daily.\n- No: not ready. The missing step needs skill development, which takes longer.\n\n**Q5. Were your Writing and Speaking bands assessed against the criteria by someone other than you, or by a consistent rubric?**\n- No: get an external or rubric-based assessment before booking; self-estimates in productive skills tend to drift.\n- Yes: ready. Book, and switch to the score stabilisation routine.\n\nBefore you book, confirm the test type, delivery options and any local timing details on the official booking page for your test centre."}$ipb$::jsonb),
    (15, 'rich_text', $ipb$The Evidence-Only Score Tracker$ipb$, $ipb${"markdown":"A score tracker is only useful if every entry is real. Use one row per assessed piece of work, never per study session.\n\n| Date | Source | Skill and band | Notes |\n|---|---|---|---|\n| Week 1 | Simulator full test | L 7.0, R 6.5 | R: four TFNG errors, passage three rushed |\n| Week 1 | Teacher-marked essay | W 6.0 | Task response: position unclear |\n| Week 2 | Recorded mock interview, rubric | S 6.5 | Part 2 ended early |\n\n### Rules for the tracker\n\n- **Source must be named.** \"Felt like a 7\" is not a source.\n- **Productive skills need a rubric or a marker.** Record which descriptor statement you matched, not just a number.\n- **No averaging across different conditions.** An untimed Reading test and a timed one are different measurements; record them separately or not at all.\n- **Look at the trend over three or more entries,** never at a single result. One high score proves you can; three consistent scores suggest you will.\n- **Record what you changed** in the notes column. When a band moves, you want to know which fix caused it.\n\nAt the end of each week, write one sentence: \"This week the evidence shows...\" If you cannot finish that sentence with real data, the week's plan should start with a timed test."}$ipb$::jsonb),
    (16, 'callout', $ipb$What Counts as Evidence$ipb$, $ipb${"label":"Only measured performance goes in the tracker","body":"Count timed practice tests taken under real conditions, Writing marked against the official criteria, Speaking recordings assessed with a rubric, and official results. Do not count untimed practice, scores from tests you have seen before, or your impression after a good study session. Keep impressions in a separate column so you can compare them with the evidence later; the gap between the two is itself useful information."}$ipb$::jsonb),
    (17, 'rich_text', $ipb$Drill 1: Band Arithmetic Sprint (8 minutes)$ipb$, $ipb${"markdown":"Set a timer for eight minutes. For each profile, write the total, the mean and the overall band. Then say whether it meets \"7.0 overall with no band below 6.5\". Answers are in the Drill Answers section; do not look until the timer ends.\n\n1. L 7.5, R 7.0, W 6.0, S 6.5\n2. L 7.0, R 7.0, W 6.5, S 6.5\n3. L 6.5, R 6.5, W 6.5, S 6.0\n4. L 7.5, R 7.0, W 6.5, S 6.5\n5. L 7.0, R 6.5, W 6.5, S 6.5\n6. L 7.0, R 7.0, W 5.5, S 6.5\n\nBonus question: Candidate D has L 7.0, R 6.5, W 6.0, S 6.5. What is the smallest number of half-band steps needed for 7.0 overall with no band below 6.5, and which skill must contain at least one of them?"}$ipb$::jsonb),
    (18, 'rich_text', $ipb$Drill 2: Diagnose the Profile (10 minutes)$ipb$, $ipb${"markdown":"Read each fictional log extract and write: the error family or bottleneck, and the single fix you would apply for the next two weeks.\n\n**Extract 1 (Listening):** \"Q8 wrote 'libary'. Q9 wrote 'two bedroom' (answer needed 'bedrooms'). Q27 wrote three words when instruction said no more than two.\"\n\n**Extract 2 (Writing, marker comment):** \"Your ideas are relevant, but each paragraph lists three reasons in one sentence each without explaining any of them.\"\n\n**Extract 3 (Reading):** \"Finished passage one at 24 minutes, passage two at 47 minutes. Guessed the last eight questions.\"\n\n**Extract 4 (Speaking, rubric note):** \"Fluent and accurate in Part 1. In Part 3, answers are one or two sentences and avoid complex structures.\"\n\n**Extract 5 (Reading):** \"Q31 and Q34: chose False; answers were Not Given. In both cases the text did not mention the claim at all, but I knew it was untrue in real life.\""}$ipb$::jsonb),
    (19, 'rich_text', $ipb$Drill 3: Upgrade the Sentence (12 minutes)$ipb$, $ipb${"markdown":"Rewrite each Band 6 shape into a Band 7 shape. Aim for precision and explanation, not rare words. Model answers are in the Drill Answers section, but yours do not need to match them; check yours against the principle named in brackets.\n\n1. (Development) \"Social media has many bad effects. It wastes time and causes stress.\"\n2. (Position) \"There are advantages and disadvantages to studying abroad, and this essay will discuss both.\"\n3. (Task 1 overview) \"In 2010 the figure was 40, in 2015 it was 55, and in 2020 it was 70.\"\n4. (Speaking Part 1 extension) \"Yes, I like reading. I read books.\"\n5. (Speaking Part 3 qualification) \"Children should learn languages because it is useful.\""}$ipb$::jsonb),
    (20, 'rich_text', $ipb$Drill Answers$ipb$, $ipb${"markdown":"### Drill 1\n\n1. Total 27.0, mean 6.75, overall 7.0. **Does not meet** the requirement: Writing 6.0 is below 6.5.\n2. Total 27.0, mean 6.75, overall 7.0. **Meets** the requirement.\n3. Total 25.5, mean 6.375, overall 6.5. Does not meet: overall too low and Speaking below 6.5.\n4. Total 27.5, mean 6.875, overall 7.0. **Meets** the requirement.\n5. Total 26.5, mean 6.625, overall 6.5. Does not meet: overall too low by one half-band step.\n6. Total 26.0, mean 6.5, overall 6.5. Does not meet: overall too low by two half-band steps, and Writing 5.5 is below the floor.\n\n**Bonus:** Candidate D's total is 26.0. Two half-band steps are needed to reach 27.0, and at least one must be in Writing, because Writing 6.0 is below the floor. Planning a third step as a safety margin is sensible.\n\n### Drill 2\n\n1. Form errors (spelling, plurals, word limit). Fix: a slow transfer check reading each answer against the instruction, plus a personal list of commonly misspelt words.\n2. Development. Fix: claim, explanation, example, link for every body paragraph; fewer ideas, each fully explained.\n3. Time allocation. Fix: fixed exit times for passages one and two, practised in every timed test.\n4. Range in Part 3. Fix: compare, rank and qualify in every Part 3 answer; practise with structures such as \"it depends on...\", \"whereas...\", \"if... then...\".\n5. Answering from world knowledge. Fix: if the text does not address the claim, the answer is Not Given, whatever you know to be true.\n\n### Drill 3 (model answers)\n\n1. \"Heavy social media use can crowd out sleep, because endless feeds have no natural stopping point, and tired students then find it harder to concentrate the next day.\"\n2. \"Although studying abroad is expensive, I believe its benefits for independence and career prospects outweigh the cost for most students who can access funding.\"\n3. \"Overall, the figure rose steadily over the decade, increasing by roughly the same amount in each five-year period.\"\n4. \"I do, mainly crime novels, which I tend to read on the train. It's the one time in the day when nobody can interrupt me.\"\n5. \"Learning a second language early seems to make pronunciation easier, so there's a strong case for it. That said, it probably works best when the language is actually used outside the classroom; otherwise children forget it quickly.\""}$ipb$::jsonb),
    (21, 'rich_text', $ipb$The 14-Day Breakthrough Block$ipb$, $ipb${"markdown":"Use this block when you are within two half-band steps of your target and have already identified your cheapest path. It assumes about ninety minutes a day; scale the volume, not the order.\n\n| Day | Main work | Evidence produced |\n|---|---|---|\n| 1 | Full timed test, all four skills | Four bands, error log |\n| 2 | Tag every error by family; update the cheapest path | Updated plan |\n| 3 | Compulsory skill: one targeted drill type, repeated | Drill log |\n| 4 | Compulsory skill: one full task, marked | One band estimate |\n| 5 | Optional skill: discipline routine on two timed sections | Section scores |\n| 6 | Compulsory skill: rewrite day four's task using feedback | Before/after comparison |\n| 7 | Rest or light review of the error rules only | None |\n| 8 | Timed sections of both target skills | Two section scores |\n| 9 | Compulsory skill: one full task, marked | One band estimate |\n| 10 | Optional skill: hardest error family only | Drill log |\n| 11 | Speaking or Writing maintenance for non-target skills | Recording or essay |\n| 12 | Compulsory skill: final targeted drill | Drill log |\n| 13 | Full timed test, real conditions | Four bands |\n| 14 | Compare days one and thirteen; decide using the booking tree | Decision |\n\nOn day fourteen, compare like with like: the same conditions, the same marking approach. If the target skills moved and nothing else fell, continue with the same block or book. If nothing moved, go to the plateau protocol."}$ipb$::jsonb),
    (22, 'rich_text', $ipb$Plateau Protocol: When Nothing Moves for Three Weeks$ipb$, $ipb${"markdown":"A plateau is three or more consecutive assessed results in a skill with no movement. It is a signal to change the method, not to add more hours of the same method.\n\n**Check 1: Is the measurement stable?** If your practice materials, timing or marker changed between results, the plateau may be noise. Fix the conditions first, then measure again.\n\n**Check 2: Are you practising or performing?** Full tests measure; they rarely teach. If most of your time goes to complete practice tests, swap half of it for targeted drills on your top error family.\n\n**Check 3: Is the feedback specific enough?** \"Improve your grammar\" is not actionable. Ask for, or create, feedback that names a criterion and a behaviour: \"complex sentences are attempted but subordinate clauses are often incomplete\".\n\n**Check 4: Are you fixing the right layer?** In Writing and Speaking, candidates often polish language when the problem is ideas and organisation. In Reading and Listening, they often add speed when the problem is accuracy.\n\n**Check 5: Is fatigue involved?** Scores that fall in the second half of a test suggest stamina. Practise full-length sessions at the same time of day as your test.\n\nAfter the checks, change one variable for two weeks and measure again. Changing several things at once makes it impossible to know what worked."}$ipb$::jsonb),
    (23, 'faq', $ipb$Advanced FAQ$ipb$, $ipb${"items":[{"question":"Should I aim for 7.5 in my strongest skill to protect the overall?","answer":"Only if your section minimums are already safe. An extra half band in a strong skill can lift the total, but it cannot fix a section that is below its floor. Protect the floors first, then use strong skills as a margin."},{"question":"Is it realistic to move two skills by half a band each in a few weeks?","answer":"It can be when one of the moves comes from discipline problems such as spelling, transfer or timing, and the other has a clearly identified behaviour to change. It is much less likely when both moves require broad language development. Your error log is the best predictor; no general timeline applies to everyone."},{"question":"How many practice tests should I take each week?","answer":"Usually one full timed test per week is enough to measure progress, with targeted drills on the other days. Taking several full tests a week often replaces learning with repetition."},{"question":"Can I trust my own Writing band estimate?","answer":"Treat it cautiously. Self-assessment tends to be generous on vocabulary and harsh on ideas, or the reverse, depending on the person. Use the public band descriptors line by line, and check your estimates against an external marker from time to time."},{"question":"What if my target organisation changes its requirement after I start?","answer":"Recalculate the cheapest path immediately using the new floors. Keep the exact wording and the date you checked it in your Lab notebook, and confirm with the organisation in writing if anything is unclear."}]}$ipb$::jsonb),
    (24, 'checklist', $ipb$Advanced Lab Checklist$ipb$, $ipb${"items":["I have copied the exact requirement, including every section minimum, from the official source.","I know my current four-band total and the total my target requires.","I have listed my compulsory half-band steps and priced each optional step using my error logs.","My plan includes one half-band step more than the arithmetic strictly needs.","Every entry in my score tracker names a real source and was produced under consistent conditions.","Every Reading and Listening error in the last two weeks is tagged by family with a reusable rule.","I have rewritten at least three of my own old Writing paragraphs into Band 7 shapes.","I have recorded Part 2 and Part 3 Speaking answers and checked them for comparing, ranking and qualifying.","I have completed all three drills and checked them against the answer key.","I will use the booking decision tree, not my mood, to decide when to book."]}$ipb$::jsonb)
)
insert into public.ielts_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select
  md5('schood-ielts-pb-section:' || 'guide-band-6-to-7-roadmap' || ':' || seed.n)::uuid,
  target.page_id,
  seed.block_type,
  seed.heading,
  'published',
  target.base_order + seed.n,
  seed.content,
  jsonb_build_object(
    'seeded_by', '20261026120100_ielts_playbook_premium_advanced_labs',
    'pack', 'advanced_lab',
    'content_revision', 'premium-advanced-lab-2026-10',
    'source_file', 'content/ielts-playbook/premium-guides/guide-band-6-to-7-roadmap.json'
  )
from target
cross join seed
on conflict (id) do nothing;

-- guide-retake-decision-premium: 25 sections, 4,600 words
with target as (
  select
    p.id as page_id,
    coalesce((
      select max(s.sort_order)
      from public.ielts_playbook_page_sections s
      where s.page_id = p.id
        and s.id <> all (array[md5('schood-ielts-pb-section:guide-retake-decision-premium:1')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:2')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:3')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:4')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:5')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:6')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:7')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:8')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:9')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:10')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:11')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:12')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:13')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:14')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:15')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:16')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:17')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:18')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:19')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:20')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:21')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:22')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:23')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:24')::uuid, md5('schood-ielts-pb-section:guide-retake-decision-premium:25')::uuid])
    ), 0) as base_order
  from public.ielts_playbook_pages p
  where p.locale_code = 'en'
    and p.slug = 'guide-retake-decision-premium'
),
seed(n, block_type, heading, content) as (
  values
    (1, 'rich_text', $ipb$Advanced Lab: How to Use This Section$ipb$, $ipb${"markdown":"The earlier sections of this guide set out the basic choice: Enquiry on Results, One Skill Retake or a full retake. This Advanced Lab turns that choice into a repeatable procedure. It is designed for the hours and days after a disappointing result, when emotion is high and decisions are expensive.\n\nWork through it in order:\n\n1. **Pause and gather facts** using the 72-hour rule.\n2. **Analyse the result** with the overall-band arithmetic and the requirement you actually need to meet.\n3. **Test each path** against its fine print: the Enquiry on Results window, One Skill Retake availability and acceptance, and full retake timing.\n4. **Run the master decision tree**, then check your reasoning against the worked cases.\n5. **Practise the logic** with the three timed drills before you make your own decision.\n\nPolicy details differ by provider, country and test centre, and they change. Wherever this Lab mentions a rule, treat it as a prompt to check the official page of your test provider and of the organisation receiving your result. Nothing here guarantees a score change or an acceptance decision."}$ipb$::jsonb),
    (2, 'rich_text', $ipb$The 72-Hour Rule: What to Do Before Deciding$ipb$, $ipb${"markdown":"For the first seventy-two hours after a result, do not book anything and do not pay for anything. Use that time to collect five facts, each written down with its source.\n\n1. **The exact requirement.** Copy the overall and section minimums from the receiving organisation's official page or your offer letter. Note the date you checked.\n2. **Your deadline.** When must the result reach the organisation? Is there any flexibility, and who decides it?\n3. **The gap.** Which sections are below their floor, and by how many half-band steps?\n4. **Your options at your centre.** Is One Skill Retake offered at your test centre for your test type and delivery mode? What is the provider's Enquiry on Results window?\n5. **Acceptance.** Does the organisation accept a One Skill Retake result? Does it accept results combined from more than one sitting? (Some organisations do; many do not. Never assume.)\n\nOnly after all five facts are written down should you move to the decision tree. Candidates who skip this step often pay for a path the organisation will not accept, or miss a deadline while waiting for a process that was never likely to help."}$ipb$::jsonb),
    (3, 'rich_text', $ipb$Reading Your Result Like an Analyst$ipb$, $ipb${"markdown":"A result is four measurements and one calculation. Read it from the bottom up.\n\n**Start with the sections, not the overall.** List each section band next to its requirement. Mark each one as \"safe\" (at or above the floor by at least half a band), \"on the line\" (exactly at the floor) or \"short\" (below the floor).\n\n**Then compare with your preparation evidence.** For each section, note your typical score in timed practice in the final three weeks before the test. A section that came in well below your consistent evidence is worth a closer look. A section that matched your evidence is probably an accurate measurement, however disappointing.\n\n**Then look at the shape.**\n\n- **One short section, the rest safe:** the classic One Skill Retake shape.\n- **Two or more short sections:** usually a full retake shape, after further preparation.\n- **No short sections, overall too low:** you need extra total points; check which single skill can supply them most cheaply.\n- **One section dramatically out of line with your evidence:** consider whether an Enquiry on Results is worth investigating.\n\nWrite the shape in one sentence at the top of your notebook. That sentence drives every later decision."}$ipb$::jsonb),
    (4, 'rich_text', $ipb$Overall Band Arithmetic for Retake Decisions$ipb$, $ipb${"markdown":"Your overall band is the mean of the four section bands, rounded to the nearest whole or half band. A mean ending in .25 rounds up to the next half band, and a mean ending in .75 rounds up to the next whole band. Means ending in .125 or .625 round down; means ending in .375 or .875 round up.\n\nThe quickest method is to add the four bands. For these common targets, the minimum totals are:\n\n| Target overall | Minimum total of four bands |\n|---|---|\n| 6.0 | 23.0 |\n| 6.5 | 25.0 |\n| 7.0 | 27.0 |\n| 7.5 | 29.0 |\n| 8.0 | 31.0 |\n\nEach half band gained in one section adds 0.5 to the total. So if one section is retaken and improves:\n\n- **L 7.0, R 7.0, W 6.0, S 6.5:** total 26.5, overall 6.5. Writing up to 6.5 makes the total 27.0, overall 7.0.\n- **L 8.0, R 7.5, W 6.5, S 6.5:** total 28.5, mean 7.125, overall 7.0. One half band in any section makes 29.0, mean 7.25, overall 7.5.\n- **L 6.0, R 6.5, W 6.5, S 6.5:** total 25.5, overall 6.5. Listening up to 7.0 makes 26.5, mean 6.625, still overall 6.5.\n\nThe third example shows the danger of retaking one skill to lift the overall: if the gap to the next threshold is more than one half-band step, a single-skill improvement of half a band will not be enough. Calculate before you book."}$ipb$::jsonb),
    (5, 'rich_text', $ipb$Enquiry on Results: When It Is Worth Considering$ipb$, $ipb${"markdown":"An Enquiry on Results (EOR) asks the provider to re-mark one or more sections. Key points to confirm on your provider's official page:\n\n- **The window.** An EOR must be requested within a limited period after the test date; many providers set this at around six weeks, but check yours.\n- **The fee.** There is a fee, which varies by provider and country. It is typically refunded if the band for a section changes. Confirm the exact terms before applying.\n- **Which sections.** You can usually choose specific sections rather than the whole test.\n- **Timing of the outcome.** Re-marking takes time. Check how long your provider indicates, and compare it with your deadline.\n\n### When an EOR is a reasonable bet\n\n- One section is far below your consistent, well-evidenced practice performance in that skill.\n- The section is Writing or Speaking, where judgement plays a larger role, and your practice was assessed against the criteria by someone reliable.\n- A single half-band change in that section would satisfy the requirement.\n\n### When it is unlikely to help\n\n- The section matched your practice evidence.\n- You need more than one half band in that section, or improvements in two sections.\n- Your evidence is mostly self-assessment.\n\nAn EOR is a review of marking, not a second attempt. Treat its outcome as uncertain and plan your preparation as if the band will not change."}$ipb$::jsonb),
    (6, 'rich_text', $ipb$EOR Green Flags and Red Flags$ipb$, $ipb${"markdown":"| Signal | Green flag (EOR worth considering) | Red flag (probably not) |\n|---|---|---|\n| Evidence | Several recent, externally marked tasks at a higher band | Mostly self-assessed practice |\n| Size of gap | One half-band step closes the requirement | Two or more steps needed |\n| Consistency | Other sections matched practice; one is clearly out of line | All sections a little lower than practice |\n| Test-day account | Nothing unusual affected your performance in that section | You ran out of time, misread a task or went off-topic |\n| Deadline | Re-marking time fits before the organisation's deadline | Deadline too close for the review to finish |\n\nThe fourth row is the one candidates find hardest to accept. If you know you wrote fewer words than required, left a task unfinished, or misunderstood the question, the mark probably reflects that, and re-marking is unlikely to change it. Be honest with yourself here; it saves both time and money."}$ipb$::jsonb),
    (7, 'rich_text', $ipb$One Skill Retake: The Fine Print to Check$ipb$, $ipb${"markdown":"One Skill Retake (OSR) lets eligible candidates retake a single section rather than the whole test. Before relying on it, confirm each of these points on the official provider page and with your receiving organisation:\n\n1. **Availability.** OSR is not offered at every test centre, for every test type or for every delivery mode. Check whether your centre offers it for the test you took.\n2. **Timing.** The retake must usually be taken within 60 days of the original test date. Count the days carefully from your actual test date.\n3. **One attempt per test.** In general you can take one OSR for each original test. Confirm the current rule.\n4. **Acceptance.** The receiving organisation must accept OSR results. Some universities, employers and visa schemes do; others require all four sections from a single sitting. Ask in writing if their page is unclear.\n5. **What happens to the old result.** In general your original result remains valid, and the OSR produces a new result that combines the retaken section with your other three. Confirm how your provider issues it.\n6. **Fee and format.** There is a fee, which varies by provider. Check the format details for your section, as delivery may differ from your original test.\n\nIf any of points 1, 2 or 4 cannot be confirmed, OSR is not yet a real option. Plan around a full retake until it is."}$ipb$::jsonb),
    (8, 'rich_text', $ipb$Which Skill Should You Retake?$ipb$, $ipb${"markdown":"When more than one skill could lift your overall, choose using these questions in order.\n\n1. **Is any section below its floor?** If exactly one is, that is your OSR skill. The decision is made.\n2. **If no section is short, which skill gives the required total most reliably?** Prefer the skill where your practice evidence is consistently above the score you received. A skill that came in at your normal level is unlikely to rise in a few weeks.\n3. **Which skill responds fastest to focused preparation for you?** Receptive skills can sometimes improve through discipline fixes (timing, transfer, spelling); productive skills often need longer feedback cycles. Use your own error logs rather than general rules.\n4. **Which skill carries the least risk on the day?** If your Speaking performance varies a lot with nerves, a Speaking OSR is a higher-variance bet than its average suggests.\n\nNever choose a skill simply because it is your favourite or because you feel unlucky in it. Choose the skill with the best combination of evidence and need."}$ipb$::jsonb),
    (9, 'rich_text', $ipb$Full Retake: When It Is the Safer Bet$ipb$, $ipb${"markdown":"A full retake is the default when the shape of your result does not fit a narrower path. It is usually the safer bet when:\n\n- **Two or more sections are below their floor.** One Skill Retake cannot fix two sections from one test.\n- **The organisation does not accept OSR results** or does not accept results combined across sittings.\n- **OSR is unavailable** at your centre, for your test type, or within the 60-day window.\n- **Your overall gap is more than one half-band step**, and no single section can realistically supply it.\n- **You need a fresh, clean result** for several organisations with different rules.\n\nA full retake has one hidden advantage: it gives you time to rebuild properly. Candidates who rush a full retake within a couple of weeks often reproduce the same profile. If your deadline allows it, use the gap to change the behaviours that produced the result, then book when your evidence says you are ready."}$ipb$::jsonb),
    (10, 'rich_text', $ipb$Combining Paths Without Losing Time$ipb$, $ipb${"markdown":"Paths can overlap, but only if you plan the calendar first. Draw a timeline with these dates:\n\n- Original test date.\n- Last day to request an EOR (from your provider's page).\n- Last day for an OSR, 60 days from the original test date (confirm with your provider).\n- The receiving organisation's deadline.\n- Realistic dates for the next full test at your centre.\n\n### Common combinations\n\n- **EOR while preparing for OSR or a full retake.** Reasonable when the EOR meets the green-flag tests and your deadline is far enough away. Prepare as if the EOR will not change anything.\n- **OSR first, full retake as backup.** Reasonable when one section is short and OSR is available and accepted. Pencil in a full test date in case the OSR does not reach the floor.\n- **Full retake only.** Simplest when two sections are short or OSR is not accepted.\n\nThe mistake to avoid is waiting for one process to finish before starting the next, then discovering the OSR window has closed. Put every deadline on a calendar on day one."}$ipb$::jsonb),
    (11, 'rich_text', $ipb$The Master Decision Tree$ipb$, $ipb${"markdown":"Use this tree after the 72-hour rule. Answer every question with written facts.\n\n**Q1. How many sections are below their required floor?**\n- Two or more: go to Q6 (full retake path).\n- Exactly one: go to Q2.\n- None (overall too low): go to Q4.\n\n**Q2. Is One Skill Retake offered at your centre for your test, within 60 days of your test date, and accepted by the receiving organisation?**\n- Yes: go to Q3.\n- No, or unconfirmed: go to Q6.\n\n**Q3. Is the short section clearly below your consistent, externally assessed practice evidence, and would one half band fix it?**\n- Yes: consider an EOR for that section if the green flags apply, and prepare for an OSR in parallel.\n- No: prepare for an OSR in that section; skip the EOR.\n\n**Q4. Can one half-band step in a single section reach the overall threshold?** (Check the totals table.)\n- Yes: go to Q5.\n- No: go to Q6.\n\n**Q5. Is OSR available and accepted?**\n- Yes: OSR in the skill chosen with the \"Which skill should you retake?\" questions.\n- No: go to Q6.\n\n**Q6. Full retake path.** Rebuild with targeted preparation, book when two consecutive timed practice tests meet every requirement, and check the next available dates against your deadline."}$ipb$::jsonb),
    (12, 'callout', $ipb$Decision Rules Card$ipb$, $ipb${"label":"Five rules to apply before you pay for anything","body":"If two or more sections are short, plan a full retake. If exactly one section is short and OSR is available and accepted, plan an OSR for that section. If the overall is short but no section is, calculate whether one half band in one section is enough before booking an OSR. If a section is far below strong external evidence and one half band would fix it, an EOR may be worth checking, but prepare as if it will not change. If you cannot confirm acceptance in writing, do not rely on the path."}$ipb$::jsonb),
    (13, 'rich_text', $ipb$Worked Case 1: One Half Band Short in Writing$ipb$, $ipb${"markdown":"**Candidate R** (fictional): L 7.5, R 7.0, W 6.0, S 7.0. Needs 7.0 overall with no band below 6.5. Deadline in ten weeks. OSR is offered at their centre and the university's admissions page confirms it accepts OSR results.\n\n**Arithmetic.** Total 27.5, overall 7.0. Only Writing is short, by one half band.\n\n**Evidence check.** Candidate R's three most recent teacher-marked essays were all at 6.0 or 6.5 on the criteria. The test result matches their evidence, so an EOR is unlikely to help.\n\n**Decision.** Skip the EOR. Book an OSR in Writing, leaving at least four weeks of preparation within the 60-day window. Training focus: task response and development in Task 2, overview and selection in Task 1. Book only after two consecutive marked essays reach 6.5 or above.\n\n**Backup.** Pencil in a full test date before the university deadline in case the OSR does not reach 6.5."}$ipb$::jsonb),
    (14, 'rich_text', $ipb$Worked Case 2: Two Skills Below Minimum$ipb$, $ipb${"markdown":"**Candidate S** (fictional): L 7.0, R 6.5, W 6.0, S 6.0. Needs 6.5 overall with no band below 6.5. Deadline in four months.\n\n**Arithmetic.** Total 25.5, mean 6.375, overall 6.5. The overall is met, but Writing and Speaking are both short by one half band.\n\n**Temptation.** \"If I retake Writing, I only need Speaking.\" That is true in principle but cannot be done with one OSR, because OSR covers one section per original test.\n\n**Decision.** Full retake path. With four months available, Candidate S spends the first six weeks on Writing development and Speaking extension, using recorded mock interviews and marked essays as evidence, then books a full test when two consecutive mocks meet every floor. Reading and Listening receive maintenance practice only, with a careful eye on Reading, which sits exactly on the floor.\n\n**Why not an EOR?** Two sections are short. Even if one changed, the other would still block the result."}$ipb$::jsonb),
    (15, 'rich_text', $ipb$Worked Case 3: Overall Fine, Deadline Tight$ipb$, $ipb${"markdown":"**Candidate T** (fictional): L 8.0, R 7.5, W 6.5, S 6.5. Needs 7.5 overall with no band below 6.5. Deadline in seven weeks.\n\n**Arithmetic.** Total 28.5, mean 7.125, overall 7.0. Every section meets its floor; the overall is one threshold short. A total of 29.0 gives a mean of 7.25, which rounds to 7.5. So one half band in any single section is enough.\n\n**Choosing the skill.** Candidate T's Reading practice evidence was consistently 8.0 in the last month, half a band above the result. Writing and Speaking practice matched the result. Reading is the best-evidenced candidate for a gain.\n\n**Acceptance and availability.** The employer accepts OSR results, and the centre offers OSR within the window.\n\n**Decision.** OSR in Reading after three weeks of timed passage practice with a strict time budget and an evidence-first approach to TFNG and YNNG questions. Because the deadline is tight, Candidate T also checks the dates of the next full test as a backup."}$ipb$::jsonb),
    (16, 'rich_text', $ipb$Worked Case 4: The Score That Does Not Fit the Evidence$ipb$, $ipb${"markdown":"**Candidate U** (fictional): L 7.5, R 7.5, W 7.0, S 6.0. Needs 7.0 overall with no band below 6.5. Deadline in three months.\n\n**Evidence check.** Over the previous two months, Candidate U recorded six mock interviews assessed against the public descriptors by an experienced teacher, with consistent results of 7.0. On test day nothing unusual happened, and Candidate U recalls speaking at length in every part.\n\n**Arithmetic.** Total 28.0, overall 7.0. Only Speaking is short, by one half band.\n\n**Decision.** This is a reasonable EOR case: strong external evidence, a single section clearly out of line, a half band would satisfy the requirement, and the deadline allows time for re-marking. Candidate U checks the EOR window and fee terms on the provider page, applies for Speaking only, and prepares for a Speaking OSR in parallel in case the band does not change.\n\n**What makes it different from Case 1:** the evidence. Candidate R's result matched their practice; Candidate U's did not."}$ipb$::jsonb),
    (17, 'rich_text', $ipb$Error Diagnosis After a Disappointing Result$ipb$, $ipb${"markdown":"Use this table to turn a disappointing section into a preparation plan, whichever path you choose.\n\n| Symptom on the result | Likely cause | Fix before the next attempt |\n|---|---|---|\n| Writing lower than expected | Under length, off-topic or unclear position | Timed tasks with a word check and a one-sentence position |\n| Writing on the floor repeatedly | Ideas listed, not developed | Claim, explanation, example, link in every paragraph |\n| Speaking lower than practice | Short answers under nerves | Rehearse extending answers in unfamiliar settings |\n| Reading lower than practice | Time ran out on the last passage | Fixed exit times for earlier passages |\n| Reading consistently stuck | TFNG and YNNG logic errors | Evidence-first routine; reject world knowledge |\n| Listening lower than practice | Lost place, then several answers missed | Read ahead; skip and recover quickly |\n| Listening marks lost on correct ideas | Spelling, plurals, word limits | Slow transfer check against the instructions |\n| All sections slightly lower | Fatigue or unfamiliar conditions | Full-length practice at the same time of day |"}$ipb$::jsonb),
    (18, 'rich_text', $ipb$Drill 1: Path Triage (10 minutes)$ipb$, $ipb${"markdown":"Set a timer for ten minutes. For each fictional profile, choose EOR, OSR, full retake, or a combination, and write one sentence of reasoning. Assume OSR is available at the centre unless stated otherwise. Answers are in the Drill Answers section.\n\n1. L 7.0, R 7.0, W 6.0, S 7.0. Needs 7.0 overall, no band below 6.5. University accepts OSR. Writing practice evidence: consistently 6.0 to 6.5.\n2. L 6.5, R 6.0, W 6.0, S 6.5. Needs 6.5 overall, no band below 6.5.\n3. L 7.5, R 7.0, W 6.5, S 6.5. Needs 7.0 overall, no band below 7.0 in Writing. Organisation does not accept OSR.\n4. L 8.0, R 8.0, W 7.0, S 6.0. Needs 7.0 overall, no band below 6.5. Speaking practice evidence: consistently 7.0, externally assessed. Deadline in four months.\n5. L 7.0, R 6.5, W 6.5, S 6.5. Needs 7.0 overall, no band below 6.5. Accepts OSR."}$ipb$::jsonb),
    (19, 'rich_text', $ipb$Drill 2: What Does the Overall Become? (8 minutes)$ipb$, $ipb${"markdown":"For each profile, calculate the current overall, then the overall after the stated retake result. Say whether the new result meets the target.\n\n1. L 6.5, R 7.0, W 6.0, S 7.0. Target 7.0 overall. Writing OSR result: 6.5.\n2. L 6.0, R 6.5, W 6.5, S 6.5. Target 7.0 overall. Listening OSR result: 7.0.\n3. L 8.0, R 7.5, W 6.5, S 6.5. Target 7.5 overall. Speaking OSR result: 7.0.\n4. L 7.0, R 6.5, W 6.0, S 6.5. Target 6.5 overall, no band below 6.5. Writing OSR result: 6.5.\n5. L 7.5, R 7.5, W 6.5, S 6.0. Target 7.0 overall, no band below 6.5. Speaking OSR result: 6.0."}$ipb$::jsonb),
    (20, 'rich_text', $ipb$Drill 3: Spot the Risky Assumption (6 minutes)$ipb$, $ipb${"markdown":"Each fictional statement contains an assumption that could cost a candidate time or money. Name the assumption and the fact that should be checked.\n\n1. \"My university accepts IELTS, so it must accept One Skill Retake.\"\n2. \"I'll request a re-mark next month when I have more time.\"\n3. \"If my OSR score is lower, I'll lose my original result.\"\n4. \"I need 7.0 overall and I'm at 6.5, so retaking my weakest skill will definitely get me there.\"\n5. \"Re-marking almost always raises Writing scores, so it's worth it.\""}$ipb$::jsonb),
    (21, 'rich_text', $ipb$Drill Answers$ipb$, $ipb${"markdown":"### Drill 1\n\n1. **OSR in Writing.** One section short, OSR accepted, and the result matches practice evidence, so an EOR is unlikely to help.\n2. **Full retake.** Reading and Writing are both short. Total 25.0 gives overall 6.5, but two sections are below the floor.\n3. **Full retake.** Writing is below the 7.0 requirement and the organisation does not accept OSR.\n4. **EOR for Speaking, with OSR preparation in parallel.** One section short, strong external evidence well above the result, a half band would fix it, and time allows.\n5. **OSR, after calculation.** Total 26.5 gives overall 6.5. One half band in any section makes 27.0 and overall 7.0, so OSR can work. Choose the skill with the strongest evidence of a quick gain.\n\n### Drill 2\n\n1. Current total 26.5, overall 6.5. New total 27.0, overall 7.0. **Meets** the target.\n2. Current total 25.5, overall 6.5. New total 26.5, mean 6.625, overall 6.5. **Does not meet** the target; one more half band elsewhere would be needed.\n3. Current total 28.5, mean 7.125, overall 7.0. New total 29.0, mean 7.25, overall 7.5. **Meets** the target.\n4. Current total 26.0, overall 6.5, Writing short. New total 26.5, overall 6.5, every section at 6.5 or above. **Meets** the target.\n5. Current total 27.5, overall 7.0, Speaking short. The OSR did not improve Speaking, so the requirement is still not met. In general the original result is not cancelled by a lower or equal OSR score, but confirm with the provider. Next step: full retake planning.\n\n### Drill 3\n\n1. Acceptance of OSR is a separate decision. Check the organisation's page or ask in writing.\n2. The EOR window is limited. Check the provider's deadline today.\n3. In general the original result remains valid. Confirm how your provider issues OSR results.\n4. A single half-band gain may not cross the threshold. Add up the four bands and check the totals table.\n5. No outcome is guaranteed. Decide using your own evidence, not general beliefs about re-marking."}$ipb$::jsonb),
    (22, 'rich_text', $ipb$The 21-Day Targeted Retake Block$ipb$, $ipb${"markdown":"Use this block when you are preparing for a One Skill Retake or a full retake with a clear single focus. About ninety minutes a day; adjust volume, not sequence.\n\n**Week 1: Rebuild the diagnosis**\n\n- Day 1: Write the 72-hour facts and the shape sentence.\n- Day 2: Timed practice in the target skill under real conditions.\n- Day 3: Tag every error or criterion gap; choose two fixes only.\n- Days 4 to 6: Drill fix one daily, with one short timed task each day.\n- Day 7: Rest, or review your rules for fifteen minutes.\n\n**Week 2: Apply under pressure**\n\n- Day 8: Full timed task or section in the target skill; get it marked.\n- Days 9 to 11: Drill fix two daily; rewrite or redo the day 8 task using feedback.\n- Day 12: Timed task or section; compare with day 8 using the same marking approach.\n- Day 13: Maintenance practice in one other skill (for a full retake, rotate).\n- Day 14: Rest.\n\n**Week 3: Stabilise**\n\n- Days 15 to 17: One timed task or section each day; no new techniques.\n- Day 18: Full test (for a full retake) or two timed target-skill sessions (for an OSR).\n- Day 19: Review errors only; update your rules.\n- Day 20: Light practice and logistics: ID, centre location, timing.\n- Day 21: Book or confirm only if your last two assessed results meet the requirement. If not, repeat weeks two and three."}$ipb$::jsonb),
    (23, 'rich_text', $ipb$Managing Deadlines with Receiving Organisations$ipb$, $ipb${"markdown":"The receiving organisation often has more flexibility than candidates expect, and less than they hope. Manage the relationship actively.\n\n- **Ask early.** As soon as you know your result does not meet the requirement, ask the organisation whether its deadline can move, whether it accepts OSR results, and whether a conditional arrangement is possible.\n- **Ask in writing.** Keep the replies. Verbal assurances are hard to rely on later.\n- **Give dates, not hopes.** \"I am taking a One Skill Retake in Writing on a specific date and expect the result by a specific date\" is more persuasive than \"I will improve soon\". Confirm result timing on your provider's page before quoting it.\n- **Check how results are sent.** Many organisations verify results directly with the provider. Make sure you know how to send or authorise the new result.\n- **Keep alternatives in view.** If one organisation cannot accept your timeline, note which others on your list might, and what they require.\n\nBeing organised does not change an organisation's rules, but it often makes the difference between a missed deadline and a workable plan."}$ipb$::jsonb),
    (24, 'faq', $ipb$Advanced FAQ$ipb$, $ipb${"items":[{"question":"Can I request an EOR and book a One Skill Retake at the same time?","answer":"Often you can prepare for both in parallel, but check your provider's rules on combining them and on what happens if the EOR changes the band in the section you planned to retake. Put both deadlines on a calendar before acting."},{"question":"Should I retake the skill I am weakest in or the one closest to the next band?","answer":"If one section is below its floor, retake that one. If none is, choose the skill with the strongest evidence that it can rise by half a band soon, and confirm with the totals table that half a band is enough."},{"question":"How soon should I take a full retake?","answer":"When two consecutive timed practice tests meet every requirement under real conditions, not when the next date happens to be available. Rushing a retake without changing the underlying behaviours often repeats the original profile."},{"question":"Will a re-mark lower my score?","answer":"A re-mark reviews your performance and the band can change, so do not request one on the assumption that it can only go up. Read your provider's terms carefully before applying."},{"question":"My result is valid for two years. Does that affect my decision?","answer":"Validity periods are set by receiving organisations, and many use two years as a guide. Check the organisation's rule, because an older result or an OSR combined with an older test may be treated differently."}]}$ipb$::jsonb),
    (25, 'checklist', $ipb$Advanced Retake Checklist$ipb$, $ipb${"items":["I waited 72 hours and wrote down the five facts, each with its source.","I copied the exact requirement, including every section minimum, from the official source.","I have written the shape of my result in one sentence.","I added my four bands and checked the totals table for my target.","I confirmed whether OSR is offered at my centre, for my test, within 60 days of my test date.","I confirmed in writing whether the receiving organisation accepts OSR results.","I checked the EOR window and fee terms on my provider's official page.","I ran the master decision tree with written facts, not feelings.","All relevant deadlines are on one calendar, including a backup full test date.","I will book only when my last two assessed results meet the requirement."]}$ipb$::jsonb)
)
insert into public.ielts_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select
  md5('schood-ielts-pb-section:' || 'guide-retake-decision-premium' || ':' || seed.n)::uuid,
  target.page_id,
  seed.block_type,
  seed.heading,
  'published',
  target.base_order + seed.n,
  seed.content,
  jsonb_build_object(
    'seeded_by', '20261026120100_ielts_playbook_premium_advanced_labs',
    'pack', 'advanced_lab',
    'content_revision', 'premium-advanced-lab-2026-10',
    'source_file', 'content/ielts-playbook/premium-guides/guide-retake-decision-premium.json'
  )
from target
cross join seed
on conflict (id) do nothing;

commit;
